// Validate and normalise the submission BEFORE anything external is
// called. Nothing downstream trusts raw input.
const body = $input.first().json.body || {};

const username = String(body.username || '').trim().toLowerCase();
const email = String(body.email || '').trim();
const description = String(body.description || '').trim();
const repoUrl = String(body.repoUrl || '').trim();

if (!/^[a-z][a-z0-9._-]{2,31}$/.test(username)) {
  throw new Error('invalid username: ' + username);
}
if (description.length < 10) {
  throw new Error('description too short');
}

// --- THE PROJECT NAME (Phase 1: accepted, not yet user-facing) --------
// A tenant is becoming a PROJECT rather than a person. For now `project`
// defaults to the username, so the namespace is byte-identical to what
// every existing tenant already has and nothing observable changes.
//
// Validated to a DNS-1123 label here, at the boundary, because it will
// become a hostname. Anything that does not fit falls back to the
// username rather than failing the submission - the portal will validate
// properly once the field is user-facing (Phase 3).
const RESERVED = [
  'default', 'kube-system', 'kube-public', 'kube-node-lease',
  'build', 'registry', 'monitoring', 'signup', 'n8n', 'dex', 'vault',
  'user1', 'user2',
  'www', 'api', 'admin', 'apps', 'auth', 'login', 'portal', 'mail',
  'ns1', 'static', 'cdn', 'root', 'system'
];
function usableProject(name) {
  if (!/^[a-z][a-z0-9-]{1,28}[a-z0-9]$/.test(name)) return false;
  if (name.indexOf('--') !== -1) return false;
  if (RESERVED.indexOf(name) !== -1) return false;
  // Prefixes that belong to the platform, not to a user.
  if (/^(kube-|proj-|tenant-)/.test(name)) return false;
  return true;
}
const rawProject = String(body.project || '').trim().toLowerCase();
// DNS-1123: FreeIPA uids may contain . and _, which are legal there and
// illegal in a namespace name, so they are mapped out rather than
// rejected by the API later.
const fromUser = username.replace(/[^a-z0-9]+/g, '-')
  .replace(/-+/g, '-').replace(/-$/, '').slice(0, 30);
const project = usableProject(rawProject) ? rawProject : fromUser;
const projectFromUser = project === fromUser;

const ns = ('tenant-' + project).replace(/-+/g, '-').replace(/-$/, '').slice(0, 63);

// Only the owner/repo shape is accepted. Anything else is treated as
// "no repo" rather than passed to GitHub - a bad URL must degrade the
// analysis, never fail the submission.
const m = repoUrl.match(/^https:\/\/github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+?)(?:\.git)?\/?$/);
const hasRepo = Boolean(m);
const owner = hasRepo ? m[1] : '';
const repo  = hasRepo ? m[2] : '';

const prompt = description.slice(0, 800);

// THE USER'S OWN PLATFORM CHOICE, from the radio on /new-project.
// Whitelisted here, at the boundary, exactly like the classifier's
// answer is: the request is external input and must not be able to name
// an arbitrary platform. Anything unrecognised becomes '' and is
// treated as 'no choice made', which routes to the classifier.
//
// 'both' is NOT an explicit platform. Its label is 'Je ne sais pas,
// aidez-moi a choisir' - it is the opt-IN to classification.
const KINDS = ['kubernetes', 'nomad', 'both'];
const rawKind = String(body.kind || '').trim().toLowerCase();
const requestedKind = KINDS.includes(rawKind) ? rawKind : '';
const userDecided = requestedKind === 'kubernetes' || requestedKind === 'nomad';

return [{ json: { username, email, description, namespace: ns, prompt,
  project, projectFromUser,
  requestedKind, userDecided,
  repoUrl, hasRepo, owner, repo } }];

// THE MODEL PICKS FROM A FIXED MENU. It cannot invent an action, name a
// namespace, or influence anything except which of three known values
// comes out of here. Anything unrecognised - a refusal, an explanation,
// an outage, a hallucinated option - becomes 'both', the safe default,
// because that asks a human to decide.
const ALLOWED = ['kubernetes', 'nomad', 'both'];

const prev = $('Analyse repo').first().json;

// WHO DECIDED, and it is reported to the user rather than blurred:
//   'user'       - they picked Kubernetes or Nomad; Groq was NEVER called
//   'classifier' - they asked for help and Groq gave a usable answer
//   'default'    - Groq was unusable (refusal, outage, nonsense)
//
// An explicit choice is honoured absolutely. This node used to derive
// `choice` from Groq's reply alone, which silently overrode every
// selection the user made - the radio had no effect on anything.
let choice, decidedBy, classifierUnsure = false;
let raw = '';

if (prev.userDecided) {
  choice = prev.requestedKind;
  decidedBy = 'user';
} else {
  try { raw = $input.first().json?.choices?.[0]?.message?.content ?? ''; } catch (e) { raw = ''; }
  const cleaned = String(raw).trim().toLowerCase().replace(/[^a-z]/g, '');
  if (cleaned === 'kubernetes' || cleaned === 'nomad') {
    choice = cleaned;
    decidedBy = 'classifier';
  } else if (cleaned === 'both') {
    // Groq genuinely could not separate them. Fall back to Kubernetes
    // and SAY SO. Kubernetes is the right default: it is the only
    // platform with a browsable tenant URL (Part 23 item 12), so an
    // uncertain answer should land where the user gets a working link.
    choice = 'kubernetes';
    decidedBy = 'classifier';
    classifierUnsure = true;
  } else {
    // A refusal, an outage, or a hallucinated option.
    choice = 'kubernetes';
    decidedBy = 'default';
    classifierUnsure = true;
  }
}
const ns = prev.namespace;

// Request bodies are built HERE, as strings, and referenced downstream as
// a single flat expression. They cannot be inlined into the HTTP nodes:
// an n8n expression containing an object literal breaks its template
// parser on the nested '}}' (see Problem #116).
const bodyNamespace = JSON.stringify({
  apiVersion: 'v1', kind: 'Namespace',
  // OWNERSHIP, recorded on the object itself. `tenant` is kept for every
  // namespace created before this change; `owner` is what the ownership
  // check and the future "my projects" list read. Both are written now
  // so a dual-read never has to guess.
  metadata: { name: ns, labels: { 'provisioned-by': 'n8n',
    tenant: prev.username, 'owner': prev.username,
    'project': prev.project } }
});
const bodyQuota = JSON.stringify({
  apiVersion: 'v1', kind: 'ResourceQuota',
  metadata: { name: ns + '-quota' },
  spec: { hard: { cpu: prev.quota.cpu, memory: prev.quota.memory } }
});
const bodyBinding = JSON.stringify({
  apiVersion: 'rbac.authorization.k8s.io/v1', kind: 'RoleBinding',
  metadata: { name: prev.username + '-binding' },
  roleRef: { apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: 'tenant-full-access' },
  subjects: [{ apiGroup: 'rbac.authorization.k8s.io', kind: 'User', name: prev.email }]
});
const bodyDeployment = JSON.stringify({
  apiVersion: 'apps/v1', kind: 'Deployment',
  metadata: { name: 'starter', labels: { app: 'starter' } },
  spec: { replicas: 1, selector: { matchLabels: { app: 'starter' } },
    template: { metadata: { labels: { app: 'starter' } },
      spec: { containers: [{ name: 'starter', image: 'nginx:alpine',
        ports: [{ containerPort: 80 }],
        resources: { requests: { cpu: '50m', memory: '64Mi' },
                     limits: { cpu: '200m', memory: '256Mi' } } }] } } }
});

return [{ json: { ...prev, choice, classifierRaw: String(raw).slice(0,120),
  decidedBy, classifierUnsure,
  classifierUsed: decidedBy === 'classifier',
  needsK8s: choice === 'kubernetes' || choice === 'both',
  bodyNamespace, bodyQuota, bodyBinding, bodyDeployment } }];

// Single place that decides what the portal is told. Every k8s node
// uses onError:continueRegularOutput, so one failure does not abort the
// run silently - the outcome is assembled here instead.
const d = $("Pick from fixed menu").first().json;

// Kubernetes returns EITHER the created object (kind: Namespace,
// ResourceQuota, ...) OR a Status object on failure
// (kind: "Status", status: "Failure", reason: ...).
// An earlier version tested  and reported every
// SUCCESS as a failure, because a created Namespace carries both a
// kind AND a status ({phase: Active}). Test the kind, not the
// presence of a status field.
function ok(nodeName) {
  try {
    const j = $(nodeName).first().json;
    if (!j) return false;
    // Success: Kubernetes returns the created object. Note a Namespace
    // carries BOTH a kind and a status ({phase: Active}), so testing
    // `!status` reported every success as a failure - the bug this
    // replaced.
    if (j.kind && j.kind !== "Status") return true;
    // Re-submission is normal, and a 409 AlreadyExists means the desired
    // state is already there. n8n surfaces that either as the k8s Status
    // body or as its own error object depending on the node, so match on
    // the substance rather than one shape.
    const s = JSON.stringify(j);
    if (s.indexOf("AlreadyExists") !== -1) return true;
    if (s.indexOf("409") !== -1) return true;
    return false;
  } catch (e) { return false; }
}

// Which deployment path actually ran? Exactly one of these nodes
// executed, so ok() returning false for the other is expected, not a
// failure - hence checking canBuild rather than OR-ing the two.
// Since Phase 2, the platform choice decides WHERE and the Dockerfile
// fact decides WHAT runs there. Both platforms can now run a built
// image, so "nomad" no longer has to be overridden to avoid an empty
// namespace - it gets the tenant's real image too.
// NEW TENANT OR A RETURNING ONE? `Create namespace` is still create-only,
// so its response answers this with no extra call: the created object
// means new, a 409 AlreadyExists means the tenant was already there and
// the Deployment/Service/Ingress were UPDATED rather than created.
// Reported because a run that silently changed nothing used to be
// indistinguishable from one that provisioned a tenant (the 2026-09-05
// bug), and 'success' should never again be ambiguous about which
// happened.
let tenantState = 'created';
try {
  const nsRaw = JSON.stringify($('Create namespace').first().json || {});
  if (nsRaw.indexOf('AlreadyExists') !== -1) tenantState = 'updated';
} catch (e) { tenantState = 'unknown'; }

const isNomad = d.choice === 'nomad';
const wantedBuild = Boolean(d.canBuild) && !isNomad;

// THE BUILD MAY HAVE BEEN REFUSED BEFORE IT EVER STARTED.
// The build namespace's ResourceQuota caps concurrency at TWO Kaniko
// pods (requests.memory 1Gi, 512Mi each). A third simultaneous
// submission has its Job rejected by the admission controller with a
// 403 'exceeded quota'.
//
// That rejection used to be reported honestly while the built Deployment
// was created anyway, pointing at an image tag nothing would ever push:
// a permanent ImagePullBackOff - and, once tenant URLs existed, a link
// GUARANTEED never to work. 'Build accepted?' now routes a refused build
// to the same starter path an unbuildable repo takes, so the tenant gets
// a real working site plus an explicit, true statement that their own
// image was not built this time.
// NOT `ok('Start image build')`. The Job's CREATION always succeeds -
// the quota refuses the POD, asynchronously, after the 201. Ask the
// Job whether it ever got a pod instead.
let podStarted = false;
try { podStarted = Boolean($('Did a build pod start?').first().json.buildPodStarted); }
catch (e) { podStarted = false; }
const buildRejected = wantedBuild && !podStarted;
const builtPath = wantedBuild && !buildRejected;
const steps = {
  namespace: ok("Create namespace"),
  quota: ok("Create quota"),
  binding: ok("Bind tenant identity"),
  // ALWAYS the starter now. The built image is no longer deployed
  // before this response: it is polled for and patched into the SAME
  // Deployment afterwards. Asking about "Deploy built image" here would
  // read false against a node that no longer exists, and the tenant
  // would be told their deployment failed when it had not.
  deployment: d.needsK8s ? ok("Create starter deployment") : null
};

// Build reporting. The workflow deliberately does NOT wait for the build
// to finish: builds take minutes and the portal times out at 60s. The
// Deployment is created immediately pointing at the image the build will
// push, and Kubernetes retries the pull until it appears. So "deployed"
// here means "the Deployment exists", and buildState says whether the
// image is ready yet.
let buildStarted = false, buildState = null;
if (builtPath) {
  buildStarted = true;
  try {
    const j = $("Check build status").first().json;
    if (j && j.status) {
      if (j.status.succeeded) buildState = "succeeded";
      else if (j.status.failed) buildState = "failed";
      else buildState = "building";
    }
  } catch (e) { buildState = "unknown"; }
}

// --- the tenant's browsable address ------------------------------------
// Reported ONLY when an Ingress was actually created. A URL that was
// requested but whose Ingress failed must not be shown to the user as if
// it worked - that is the same class of lie as reporting a placeholder
// as their own image.
const site = ok('Create ingress') && ok('Create service');
let siteUrl = null, siteHost = null, sitePortSource = null;
if (site) {
  try {
    const s = $('Decide site').first().json;
    siteUrl = s.siteUrl; siteHost = s.siteHost; sitePortSource = s.portSource;
  } catch (e) { /* Decide site did not run: leave null */ }
}
// A built image's Deployment is created BEFORE the build finishes and
// sits in ImagePullBackOff until the image is pushed, so the link is
// live only once the build succeeded. The starter is up immediately.
const siteReady = site && (!builtPath || buildState === 'succeeded');

const provisioned = steps.namespace && steps.quota && steps.binding
  && (steps.deployment === null || steps.deployment === true);

// Nomad IS automated now, for the `nomad` choice only. `both` is
// deliberately untouched in this pass: it remains a human-review
// fallback, not a dual-deployment feature.
const nomadAttempted = isNomad;
// On the Nomad side too: a buildable repo beats the placeholder. Same
// fact-before-opinion ordering as the Kubernetes path.
const nomadBuilt = nomadAttempted && Boolean(d.canBuild);
let nomadJob = null, nomadNamespaceMissing = false;
if (nomadAttempted) {
  try {
    const j = $(nomadBuilt ? "Submit Nomad job (built image)"
                           : "Submit Nomad job").first().json;
    if (j && j.EvalID) nomadJob = "submitted";
    else {
      const s = JSON.stringify(j);
      // Nomad answers HTTP 500 with "nonexistent namespace" - NOT 403 -
      // when the tenant namespace has not been created. Verified against
      // the live API rather than assumed, because guessing 403 here
      // reported a real, expected condition as a generic failure.
      if (s.indexOf("nonexistent namespace") !== -1 ||
          s.indexOf("Permission denied") !== -1) {
        nomadNamespaceMissing = true; nomadJob = "blocked";
      } else nomadJob = "failed";
    }
  } catch (e) { nomadJob = "failed"; }
}
// `choice` can no longer BE 'both': an explicit choice is honoured, and
// an uncertain classifier now resolves to Kubernetes with a note rather
// than parking the request for a human. nomadPending is retired and
// pinned false so any old reader sees a definite answer, not a stale one.
// NAME COLLISION. Phase 1 cannot be reached by a normal submission
// (project defaults to the username), but the path is real and reported
// so the refusal is honest the moment names become user-chosen.
let nameTaken = false, ownerUnknown = false;
try {
  const o = $('Is it ours to use?').first().json;
  nameTaken = Boolean(o.nameTaken);
  ownerUnknown = Boolean(o.ownerUnknown);
} catch (e) { /* the check did not run */ }

// A refused name did not create OR update anything. Reporting
// 'updated' here - which the namespace 409 would otherwise imply - would
// claim work that never happened, on the one path where the user most
// needs to be told plainly that nothing was done.
if (nameTaken) tenantState = 'refused';

const nomadPending = false;

// --- the Nomad tenant's browsable address -----------------------------
// Kubernetes' Traefik fronts a Nomad job on another host through a
// selector-less Service + a hand-built EndpointSlice carrying the
// allocation's REAL host:port. Same honesty rule as the Kubernetes path:
// a URL is reported only when every object came back real AND a genuine
// port was read. A link that is guaranteed to 502 is worse than none.
let nomadSiteUrl = null, nomadSiteHost = null, nomadSiteReady = false;
let nomadPort = null, nomadAllocStatus = null;
if (nomadAttempted) {
  let addr = null;
  try { addr = $('Decide Nomad site').first().json; } catch (e) { addr = null; }
  const wired = ok('Create nomad service') && ok('Create nomad endpoints')
                && ok('Create nomad ingress');
  if (addr) {
    nomadPort = addr.nomadPort || null;
    nomadAllocStatus = addr.allocStatus || null;
    // BOTH halves required: the objects exist AND a real port was read.
    // haveAddr is false when Nomad had not placed the allocation yet, in
    // which case there is genuinely nothing to point at.
    if (wired && addr.haveAddr) {
      nomadSiteUrl = addr.siteUrl; nomadSiteHost = addr.siteHost;
      // Ready only once the allocation is actually running. A built
      // image's job sits pending until the image is pushed, exactly like
      // the Kubernetes ImagePullBackOff case.
      nomadSiteReady = Boolean(addr.allocRunning);
    }
  }
}

// ONE pair of fields for the portal whichever platform ran, so the page
// needs no per-platform branch and cannot show a Kubernetes URL for a
// Nomad tenant or vice versa.
const finalSiteUrl = nomadAttempted ? nomadSiteUrl : siteUrl;
const finalSiteHost = nomadAttempted ? nomadSiteHost : siteHost;
const finalSiteReady = nomadAttempted ? nomadSiteReady : siteReady;

return [{ json: {
  provisioned, username: d.username, namespace: d.namespace,
  choice: d.choice, classifierUsed: d.classifierUsed, steps, nomadPending,
  // Who actually decided the platform, so the portal can say so instead
  // of implying the user's selection was applied when it was not.
  // 'created' = new tenant, 'updated' = existing tenant re-provisioned.
  tenantState,
  // Refused: the name belongs to someone else, or ownership could not
  // be established. Either way nothing was deployed.
  nameTaken, ownerUnknown,
  project: d.project || null,
  decidedBy: d.decidedBy, requestedKind: d.requestedKind || null,
  classifierUnsure: Boolean(d.classifierUnsure),
  // Repo analysis is reported honestly: repoAnalysed says whether the
  // link was actually READ, not merely supplied. A rate limit or a
  // private repo shows up here as false with the default quota.
  repoProvided: Boolean(d.hasRepo), repoAnalysed: Boolean(d.repoAnalysed),
  quotaTier: d.quotaTier, quota: d.quota, readmeChars: d.readmeChars || 0,
  languages: Object.keys(d.languages || {}).slice(0, 6),
  hasDockerfile: Boolean(d.hasDockerfile), hasCompose: Boolean(d.hasCompose),
  // "built" vs "fallback" stated plainly - never implying a real image
  // was produced when the starter placeholder was deployed instead.
  deployPath: builtPath ? "built"
    : (d.needsK8s ? "fallback"
    : (nomadAttempted ? (nomadBuilt ? "nomad-built" : "nomad") : "none")),
  nomadNamespace: nomadAttempted ? d.nomadNamespace : null,
  nomadJob, nomadNamespaceMissing,
  // "we ran YOUR image" is never conflated with "we ran a placeholder".
  nomadPath: nomadAttempted ? (nomadBuilt ? "built" : "starter") : null,
  nomadImage: nomadBuilt ? d.nomadImageRef : null,
  nomadBuildStarted: nomadBuilt ? ok("Start image build for Nomad") : null,
  buildStarted, buildState, image: builtPath ? d.imageRef : null,
  // Said plainly rather than folded into a generic failure: the platform
  // was busy, the tenant's own image was not built, a working placeholder
  // site was deployed instead.
  buildRejected,
  // BOTH platforms have a browsable URL now. The Nomad one is bridged
  // through a selector-less Service + EndpointSlice carrying the
  // allocation's real host:port (added 2026-09-05); the correction to
  // the old 'Kubernetes tenants only' comment is deliberate.
  //
  // STALENESS, stated because it is real: the Nomad port is a SNAPSHOT.
  // Nothing watches Nomad, so if that allocation is later rescheduled it
  // returns on a new random port and this URL 502s until the tenant
  // resubmits. Part 23 item 17.
  siteUrl: finalSiteUrl, siteHost: finalSiteHost, siteReady: finalSiteReady,
  sitePortSource,
  // The Kubernetes-path values are kept under their own names so a
  // reader can still tell which path produced what.
  k8sSiteUrl: siteUrl, nomadSiteUrl, nomadSitePort: nomadPort,
  nomadAllocStatus,
  // Out of scope for this pass, and said rather than silently ignored.
  composeUnsupported: Boolean(d.hasCompose && !d.hasDockerfile),
  note: nomadNamespaceMissing
    ? 'Nomad space not created yet: namespace creation needs an operator (management token).'
    : (d.classifierUnsure ? 'Classifier was unsure; defaulted to Kubernetes.'
    // Said plainly instead of showing a link that cannot work: the job
    // was submitted but Nomad had not placed it yet when we answered.
    : (nomadAttempted && !nomadSiteUrl && nomadJob === 'submitted'
        ? 'Job submitted; no address yet because Nomad had not placed it when we answered.'
        : null))
} }];

// Turn whatever GitHub returned into FACTS. Every lookup is wrapped:
// a rate limit (60/hr unauthenticated), a private repo, a deleted repo
// or a GitHub outage must degrade this to text-only classification and
// the default quota - never fail the submission.
const v = $('Validate input').first().json;
const NL = String.fromCharCode(10);

function node(name) {
  try { return $(name).first().json; } catch (e) { return null; }
}

// --- languages -------------------------------------------------------
let languages = {}, langCount = 0;
const L = node('Repo languages');
if (L && !L.error && typeof L === 'object' && !Array.isArray(L)) {
  for (const k of Object.keys(L)) {
    if (typeof L[k] === 'number') { languages[k] = L[k]; langCount++; }
  }
}

// --- readme ----------------------------------------------------------
// Requested with Accept: vnd.github.raw, so this is plain text. n8n may
// hand it back as a string or wrapped under .data depending on content
// type sniffing, so both shapes are accepted.
let readme = '';
const R = node('Repo readme');
if (R && !R.error) {
  if (typeof R === 'string') readme = R;
  else if (typeof R.data === 'string') readme = R.data;
}
readme = String(readme).slice(0, 1500);

// --- root file listing ------------------------------------------------
// GitHub returns a JSON ARRAY here, and n8n splits an array response into
// N SEPARATE ITEMS - so .first().json yields only the first file, never
// the listing. Use .all() and map. This silently made hasDockerfile
// permanently false, which Part B depends on. See Problem #118.
let files = [], hasDockerfile = false, hasCompose = false;
// THE ACTUAL FILENAME, not an assumed one. Git is case-sensitive and
// `dockerfile` is as valid as `Dockerfile`; Kaniko is handed this
// verbatim rather than a guess (Problem #143).
let dockerfileName = '';
let defaultBranch = '';
try {
  const items = $('Repo contents').all();
  for (const it of items) {
    const f = it.json;
    if (f && typeof f.name === 'string') {
      files.push(f.name);
      // download_url embeds the default branch:
      // raw.githubusercontent.com/<owner>/<repo>/<BRANCH>/<path>
      // Free - avoids a 4th GitHub API call against a 60/hour budget.
      if (!defaultBranch && typeof f.download_url === 'string') {
        const dm = f.download_url.match(/raw\.githubusercontent\.com\/[^/]+\/[^/]+\/([^/]+)\//);
        if (dm) defaultBranch = dm[1];
      }
      const n = f.name.toLowerCase();
      if (n === 'dockerfile') { hasDockerfile = true; dockerfileName = f.name; }
      if (n === 'docker-compose.yml' || n === 'docker-compose.yaml' ||
          n === 'compose.yml' || n === 'compose.yaml' ||
          n === 'compose.override.yml') hasCompose = true;
    }
  }
} catch (e) { /* node did not run, or GitHub refused: stay empty */ }

// Did the analysis actually produce anything? Used to tell the user the
// truth about whether their link was read.
const repoAnalysed = v.hasRepo && (langCount > 0 || readme.length > 0 || files.length > 0);

// --- QUOTA TIER: computed from FACTS, never chosen by the model --------
// Three fixed tiers, not a formula. `standard` is byte-identical to the
// existing user1/user2 pattern (Part 8) so the common case is unchanged,
// and it is also the fallback whenever the repo could not be read.
let quotaTier = 'standard';
if (repoAnalysed) {
  if (langCount >= 3 || hasCompose) quotaTier = 'large';
  else if (langCount <= 1 && !hasCompose) quotaTier = 'small';
}
const TIERS = {
  small:    { cpu: '500m',  memory: '1Gi' },
  standard: { cpu: '1500m', memory: '2560Mi' },
  large:    { cpu: '2000m', memory: '3Gi' }
};
const quota = TIERS[quotaTier];


// --- build path -------------------------------------------------------
// A real image is built ONLY when the repo has a Dockerfile at its root.
// Scope limit: single-Dockerfile projects. Multi-container compose is out
// of scope for this pass and is deliberately NOT attempted.
const canBuild = Boolean(v.hasRepo && hasDockerfile && defaultBranch);
const buildTag = 'build-' + Math.floor(Date.now() / 1000);
const imageRef = '10.43.200.50:5000/' + v.namespace + '/app:' + buildTag;
const jobName = ('build-' + v.username + '-' + buildTag).slice(0, 60);

const bodyBuildJob = JSON.stringify({
  apiVersion: 'batch/v1', kind: 'Job',
  metadata: { name: jobName, labels: { tenant: v.username } },
  spec: {
    activeDeadlineSeconds: 900,
    backoffLimit: 0,
    ttlSecondsAfterFinished: 3600,
    template: {
      metadata: { labels: { app: 'kaniko-build', tenant: v.username } },
      spec: {
        restartPolicy: 'Never',
        serviceAccountName: 'builder',
        automountServiceAccountToken: false,
        securityContext: { seccompProfile: { type: 'RuntimeDefault' } },
        containers: [{
          name: 'kaniko',
          image: 'gcr.io/kaniko-project/executor:v1.23.2',
          args: [
            '--context=git://github.com/' + v.owner + '/' + v.repo +
              '.git#refs/heads/' + defaultBranch,
            // The real filename. A hardcoded 'Dockerfile' fails on any
            // repo that spells it lowercase (Problem #143).
            '--dockerfile=' + (dockerfileName || 'Dockerfile'),
            '--destination=' + imageRef,
            '--insecure', '--skip-tls-verify', '--single-snapshot',
            '--verbosity=info'
