          securityContext: {
            privileged: false,
            allowPrivilegeEscalation: false,
            // Minimum found by attempting the real build and reading each
            // error in turn: CHOWN, then FOWNER, then DAC_OVERRIDE.
            // Unprivileged, no Docker socket, no host mounts, no k8s API.
            capabilities: { drop: ['ALL'], add: ['CHOWN','FOWNER','DAC_OVERRIDE'] }
          },
          resources: {
            requests: { cpu: '300m', memory: '512Mi' },
            limits: { cpu: '1', memory: '1Gi' }
          }
        }]
      }
    }
  }
});

