// It is created immediately and will sit in ImagePullBackOff until the
// build pushes - Kubernetes retries pulls with backoff, so it starts by
// itself. This is why the workflow does not block: a build takes minutes
// and the portal's HTTP timeout is 60s.
const bodyBuiltDeployment = JSON.stringify({
  apiVersion: 'apps/v1', kind: 'Deployment',
  metadata: { name: 'app', labels: { app: 'app', 'built-by': 'kaniko' } },
  spec: {
    replicas: 1,
    selector: { matchLabels: { app: 'app' } },
    template: {
      metadata: { labels: { app: 'app' } },
      spec: {
        containers: [{
          name: 'app', image: imageRef, imagePullPolicy: 'IfNotPresent',
          resources: {
            requests: { cpu: '50m', memory: '64Mi' },
            limits: { cpu: '500m', memory: '512Mi' }
          }
        }]
      }
    }
  }
});


// --- Nomad path -------------------------------------------------------
// Tenant Nomad namespaces are named tenant-<user>, matching the
// Kubernetes convention AND matching the glob in n8n's ACL policy
// (namespace "tenant-*"), which is what keeps this token out of user1,
// user2 and default.
//
// SCOPE LIMIT, proven not assumed: creating a Nomad NAMESPACE or ACL
// POLICY is a management-only operation - a scoped token gets 403. n8n
// therefore submits jobs into a namespace that must already exist, and
// says so plainly when it does not. See the handoff.
const nomadNamespace = v.namespace;   // tenant-<user>

// The starter job mirrors the Kubernetes nginx:alpine fallback: a known
// -good public image, no build required. http-echo is what default/hello
// already runs on this cluster, so the driver and image are proven here.
const nomadJobId = 'starter';
// UPGRADE IN PLACE, once the build actually exists. Same object as the
// starter, same selector (a Deployment's selector is immutable anyway),
// so this is a rolling update rather than a second Deployment plus a
// Service-selector move (Part 23 item 16).
const bodyRepoUpgrade = JSON.stringify({
  apiVersion: 'apps/v1', kind: 'Deployment',
  metadata: { name: 'starter', labels: { app: 'starter', 'built-by': 'kaniko' } },
  spec: {
    replicas: 1,
    selector: { matchLabels: { app: 'starter' } },
    template: {
      metadata: { labels: { app: 'starter' } },
      spec: { containers: [{
        name: 'app', image: imageRef, imagePullPolicy: 'IfNotPresent',
        resources: { requests: { cpu: '50m', memory: '64Mi' },
                     limits: { cpu: '500m', memory: '512Mi' } }
      }] }
    }
  }
});

const bodyNomadJob = JSON.stringify({
  Job: {
    ID: nomadJobId, Name: nomadJobId, Type: 'service',
    Namespace: nomadNamespace, Datacenters: ['*'],
    TaskGroups: [{
      Name: 'app', Count: 1,
      Networks: [{ DynamicPorts: [{ Label: 'http', To: 5678 }] }],
      Tasks: [{
        Name: 'app', Driver: 'docker',
        Config: {
          image: 'hashicorp/http-echo:latest',
          args: ['-text=' + v.username + ' is running on Nomad',
                 '-listen=:5678'],
          ports: ['http']
        },
        Resources: { CPU: 100, MemoryMB: 64 }
      }]
    }]
  }
});


// Nomad pulls over the LAN address, not the ClusterIP. Kaniko pushes to
// 10.43.200.50:5000 (in-cluster) and k3s pulls from there; Nomad runs on
// a separate VM that cannot route to a ClusterIP, so it uses the
// registry-external LoadBalancer. SAME image, same digest, two doors.
const nomadImageRef = imageRef.replace('10.43.200.50:5000', '192.168.1.50:5000');

// A Nomad job running the tenant's OWN built image.
// No port mapping is declared: the port an arbitrary repo listens on is
// unknown, and guessing one would produce a job that looks healthy while
// exposing nothing. The Kubernetes built-image path makes the same
// choice. Exposing tenant services is a separate piece of work.
// bodyNomadBuiltJob is MOVED: see below. It needs `appPort`, which is not
// computed until further down, so constructing it here read undefined.

// --- the port the tenant's app actually listens on ---------------------
// An Ingress pointing at the wrong port produces a CLICKABLE LINK THAT
// 502s, which is worse for a user than no link at all. So the port is
// READ from the Dockerfile's EXPOSE rather than assumed.
//
// Fetched from raw.githubusercontent.com, which is a DIFFERENT HOST from
// api.github.com and does not spend its 60/hour budget. Degrades like
// every other lookup here: no Dockerfile, no EXPOSE, a private repo or an
// outage all fall back to 80 and SAY SO through portSource, which the
// portal shows the user rather than hiding.
let appPort = 80, portSource = 'default';
{
  const D = node('Repo dockerfile');
  let text = '';
  if (D && !D.error) {
    if (typeof D === 'string') text = D;
    else if (typeof D.data === 'string') text = D.data;
  }
  // Last EXPOSE wins, matching Docker: a later build stage overrides an
  // earlier one. Only the FIRST port of a multi-port EXPOSE is used -
  // serving one of several is right; guessing which of several is not
  // something this can do, so it is not attempted.
  const lines = String(text).split(/\r?\n/);
  for (const ln of lines) {
    const m = ln.match(/^\s*EXPOSE\s+(\d{1,5})/i);
    if (m) {
      const p = parseInt(m[1], 10);
      if (p >= 1 && p <= 65535) { appPort = p; portSource = 'EXPOSE'; }
    }
  }
}

// --- the tenant's browsable address ------------------------------------
// The NAMESPACE is the host label, not the raw username. Usernames may
// contain dots (amine.beji); the namespace is already sanitised to
// [a-z0-9-] and <=63 chars by Validate input, so reusing it makes host
// and namespace IDENTICAL rather than merely both-valid.
//
// NOT because a wildcard would fail to match a dotted name - it would
// match fine. RFC 4592: *.apps.cloudlab.internal covers any name below
// apps.cloudlab.internal at ANY depth. Measured against the live zone:
// a.b.c.apps.cloudlab.internal and tenant-amine.beji.apps.cloudlab.internal
// both resolve. An earlier comment here claimed the opposite.
// --- the built Nomad job, now that appPort is known -------------------
// A dynamic port is REQUIRED, not decorative: without a Networks block
// the container publishes nothing and there is no allocation port to
// read, so the tenant could never have a URL. `To` maps the random host
// port to the port the Dockerfile actually EXPOSEs.
// The Service must follow the port the Dockerfile declared, or the
// upgraded pod listens on 3000 while the Service still points at 80 and
// the tenant gets a clickable link that 502s - Problem #130's shape.
// Applied AFTER the new pod is up, never before: pointing the Service at
// a port nothing listens on yet breaks the site during the rollout.
const bodyRepoUpgradeSvc = JSON.stringify({
  apiVersion: 'v1', kind: 'Service',
  metadata: { name: 'site-k8s', labels: { 'provisioned-by': 'n8n' } },
  spec: { selector: { app: 'starter' },
    ports: [{ name: 'http', port: 80, targetPort: appPort || 80 }] }
});

const bodyNomadBuiltJob = JSON.stringify({
  Job: {
    ID: nomadJobId, Name: nomadJobId, Type: 'service',
    Namespace: nomadNamespace, Datacenters: ['*'],
    TaskGroups: [{
      Name: 'app', Count: 1,
      Networks: [{ DynamicPorts: [{ Label: 'http', To: appPort }] }],
      // SURVIVE THE BUILD RACE. This job is submitted while Kaniko is
      // still pushing, so the first pulls WILL fail. Nomad's default is
      // attempts:2/mode:'fail', which kills the allocation permanently
      // ~30s in and leaves a dead job behind a live URL. Retry patiently
      // instead, so the task starts by itself once the image lands -
      // the same self-healing Kubernetes gets from ImagePullBackOff.
      RestartPolicy: { Attempts: 20, Interval: 3600000000000,
                       Delay: 20000000000, Mode: 'delay' },
      Tasks: [{
        Name: 'app', Driver: 'docker',
        Config: { image: nomadImageRef, ports: ['http'] },
        Resources: { CPU: 200, MemoryMB: 256 }
      }]
    }]
  }
});

// --- which manifest describes how to build this project? --------------
// First match wins, in the order a human would look. '' means we found
// none, which is itself a fact the generator is told rather than left
// to infer from silence.
const MANIFESTS = ['package.json', 'requirements.txt', 'go.mod',
                   'Gemfile', 'composer.json', 'pyproject.toml',
                   'Cargo.toml', 'pom.xml'];
const lowerFiles = files.map(f => String(f).toLowerCase());
let manifestName = '';
for (const m of MANIFESTS) {
  if (lowerFiles.indexOf(m.toLowerCase()) !== -1) { manifestName = m; break; }
}
// A static site has no manifest at all, and that is the EASIEST case to
// generate for - so absence is reported, never treated as a failure.
const looksStatic = !manifestName &&
  lowerFiles.some(f => f === 'index.html' || f.endsWith('.html'));

const siteHost = v.namespace + '.apps.cloudlab.internal';
const siteUrl = 'http://' + siteHost + '/';

// --- the classifier prompt -------------------------------------------
// README is the primary signal when it has real content; language stats
// are the fallback that exists even when the README is missing or empty.
const SYS = 'You classify hosting requests for a small cloud platform. ' +
  'Reply with EXACTLY one word from this list and nothing else: kubernetes, nomad, both. ' +
  'kubernetes = needs to scale, has several components, or must stay available continuously. ' +
  'nomad = simple and small, quick to deploy, a single tool or prototype. ' +
  'both = the request is vague, or genuinely needs both kinds of workload. ' +
  'Answer with one word only. Never explain.';

let user = 'What the person wrote: ' + v.prompt;
if (langCount > 0) {
  const top = Object.keys(languages).sort((a,b) => languages[b]-languages[a]).slice(0,6);
  // NL is built with fromCharCode: a literal newline escape
  // inside this string does not survive the JSON round-trip.
  user += NL + NL + 'Languages in their repository: ' + top.join(', ') + '.';
}
if (files.length > 0) {
  // NL is built with fromCharCode: a literal newline escape
  // inside this string does not survive the JSON round-trip.
  user += NL + NL + 'Files at the repository root: ' + files.slice(0,25).join(', ') + '.';
}
if (readme.trim().length > 40) {
  // NL is built with fromCharCode: a literal newline escape
  // inside this string does not survive the JSON round-trip.
  user += NL + NL + 'Their README (most reliable signal, may be truncated):' + NL + readme;
}

const groqBody = JSON.stringify({
  model: 'openai/gpt-oss-20b', temperature: 0, max_tokens: 512,
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: SYS },
    { role: 'user', content: user }
  ]
});

return [{ json: { ...v, languages, langCount, readmeChars: readme.length,
  defaultBranch, canBuild, imageRef, jobName, bodyBuildJob, bodyBuiltDeployment,
  nomadNamespace, nomadJobId, bodyNomadJob,
  nomadImageRef, bodyNomadBuiltJob,
  files, hasDockerfile, hasCompose, dockerfileName, repoAnalysed, quotaTier, quota,
  appPort, portSource, siteHost, siteUrl,
  manifestName, looksStatic,
  groqBody } }];

// Which deployment actually landed decides what the Service selects and
// which port it targets. Exactly one of the two ran.
const a = $('Analyse repo').first().json;

function ok(name) {
  try {
    const j = $(name).first().json;
    if (!j) return false;
    // Same shape test as Build result: a created object carries a kind,
    // and a Namespace carries BOTH a kind and a status - so test the
    // kind, never the presence of a status field (Problem #117).
    if (j.kind && j.kind !== 'Status') return true;
    const s = JSON.stringify(j);
    return s.indexOf('AlreadyExists') !== -1 || s.indexOf('409') !== -1;
  } catch (e) { return false; }
}

// The built image is no longer deployed before the response - it is
// polled for and patched in afterwards, so at THIS point the only
// thing serving is always the starter. Keeping ok('Deploy built
// image') here would silently read false forever against a node
// that no longer exists.
const builtRan = false;
const starterRan = !builtRan && ok('Create starter deployment');
const selector = builtRan ? 'app' : 'starter';
// The starter is nginx:alpine, where 80 is a FACT rather than an
// inference. Only the built path carries a port read out of a Dockerfile,
// so only it can be wrong - and only it reports portSource to the user.
const targetPort = builtRan ? a.appPort : 80;
const portSource = builtRan ? a.portSource : 'known';
const hasSite = builtRan || starterRan;

// The Service always publishes on 80 and maps to the app's real port, so
// the Ingress backend is ONE fixed shape whichever path ran.
const bodyService = JSON.stringify({
  apiVersion: 'v1', kind: 'Service',
  metadata: { name: 'site-k8s', labels: { 'provisioned-by': 'n8n' } },
  spec: { selector: { app: selector },
    ports: [{ name: 'http', port: 80, targetPort: targetPort }] }
});
const bodyIngress = JSON.stringify({
  apiVersion: 'networking.k8s.io/v1', kind: 'Ingress',
  metadata: { name: 'site', labels: { 'provisioned-by': 'n8n' } },
  spec: { ingressClassName: 'traefik',
    rules: [{ host: a.siteHost, http: { paths: [{ path: '/', pathType: 'Prefix',
      backend: { service: { name: 'site-k8s', port: { number: 80 } } } }] } }] }
});

return [{ json: { hasSite, builtRan, starterRan, selector, targetPort,
  portSource, siteHost: a.siteHost, siteUrl: a.siteUrl,
  bodyService, bodyIngress } }];

// Did the build Job actually get a POD, or was it admitted and then
// starved by the ResourceQuota?
//
// The quota caps the build namespace at TWO concurrent Kaniko pods
// (requests.memory 1Gi, 512Mi each). A third submission's Job is
// CREATED normally - 201, kind:Job - and only its pod is refused, so
// the creation response proves nothing. The Job's own status does:
//
//   pod running  -> {"active":1,"ready":1,...}
//   pod refused  -> {"ready":0,...}   <- no `active` key
//
// Verified against the live API during a deliberate three-way
// concurrent submission, not inferred from documentation.
let st = null;
try { st = $('Check build status').first().json.status || null; } catch (e) { st = null; }

const active = st && Number(st.active) > 0;
const done = st && Number(st.succeeded) > 0;
// A build that already FAILED is not a reason to fall back to the
// starter - the tenant's image was attempted and lost on its own
// merits, which is a different message from 'the platform was busy'.
const failed = st && Number(st.failed) > 0;
const buildPodStarted = Boolean(active || done || failed);

return [{ json: { buildPodStarted, buildActive: Boolean(active),
  buildDone: Boolean(done), buildFailedEarly: Boolean(failed),
  // Distinguishes 'refused by quota' from 'job missing entirely'.
  jobStatusSeen: st !== null } }];

// WHICH allocation, and it matters more than it looks. After a
// resubmission the job has BOTH the old stopped allocation and the new
// running one, and the old one carries the OLD port. Picking the wrong
// entry would wire the tenant's URL to a port nothing listens on - the
// exact stale-object failure the Kubernetes side was just fixed for.
// So: prefer running, and among those the highest CreateIndex.
// EMPTY-SAFE. With no Nomad namespace the job does not exist, so the
// list call 404s and this node receives one empty/error item rather
// than allocations. That is a NORMAL, operator-fixable state, and it
// must flow on to Build result so the user gets the real reason - not
// stop the branch and leave the portal timing out on no answer at all.
let allocs = [];
try {
  allocs = $input.all().map(i => i.json).filter(x => x && x.ID);
} catch (e) { allocs = []; }

const running = allocs.filter(x => x.ClientStatus === 'running');
const pool = running.length ? running : allocs;
pool.sort((x, y) => (y.CreateIndex || 0) - (x.CreateIndex || 0));
const chosen = pool[0] || null;

return [{ json: {
  allocId: chosen ? chosen.ID : '',
  allocStatus: chosen ? chosen.ClientStatus : null,
  allocCount: allocs.length, runningCount: running.length,
  // An empty allocId is a real, expected state (nothing placed yet). It
  // is reported rather than papered over, and it ends with NO url.
  havePlacement: Boolean(chosen && chosen.ClientStatus === 'running')
} }];

