// never assumed: the port is dynamic and changes on every placement.
//
// Source of truth is AllocatedResources.Shared.Ports[] -> {HostIP, Value}.
// Shared.Networks[].DynamicPorts[] is the fallback for older shapes.
// NOTE the list endpoint /v1/job/<id>/allocations returns a SUMMARY with
// no AllocatedResources at all - the detail fetch is not optional.
const a = $('Analyse repo').first().json;
const pick = $('Pick the live allocation').first().json;
// May be an error item or empty when nothing was placed - every read
// below is already guarded, and haveAddr ends up false, which means no
// URL is reported rather than a broken one.
let alloc = {};
try { alloc = $input.first().json || {}; } catch (e) { alloc = {}; }

let host = null, port = null;
try {
  const res = alloc.AllocatedResources || {};
  const shared = res.Shared || {};
  const ports = shared.Ports || [];
  const p = ports.find(x => x.Label === 'http') || ports[0];
  if (p) { host = p.HostIP || null; port = p.Value || null; }
  if (!port) {
    for (const n of (shared.Networks || [])) {
      const dyn = n.DynamicPorts || [];
      const d = dyn.find(x => x.Label === 'http') || dyn[0];
      if (d && d.Value) { host = host || n.IP; port = d.Value; break; }
    }
  }
} catch (e) { host = null; port = null; }

