// the same rule the Kubernetes path follows, because a link that is
// guaranteed to 502 is worse for a user than an honest 'not yet'.
const haveAddr = Boolean(host && port);
const allocRunning = alloc.ClientStatus === 'running';

// The Service carries NO selector: nothing in this cluster backs it, the
// EndpointSlice does. For a selector-less Service the SLICE's port is
// authoritative and the Service's targetPort is ignored - matched by
// port NAME - which is why the port lives in the slice below and any
// assertion about it must read the slice, not the Service.
const bodyNomadService = JSON.stringify({
  apiVersion: 'v1', kind: 'Service',
  metadata: { name: 'site-nomad-svc', labels: { 'provisioned-by': 'n8n' } },
  spec: { ports: [{ name: 'http', port: 80, protocol: 'TCP' }] }
});

// port is the value READ above. If this is ever replaced by a constant,
// the tenant gets a link that cannot work - wfcheck.js asserts against it.
const bodyNomadSlice = JSON.stringify({
  apiVersion: 'discovery.k8s.io/v1', kind: 'EndpointSlice',
  metadata: { name: 'site-nomad',
    labels: { 'kubernetes.io/service-name': 'site-nomad-svc', 'provisioned-by': 'n8n' } },
  addressType: 'IPv4',
  ports: [{ name: 'http', port: port || 0, protocol: 'TCP' }],
