  // after the build succeeded. With it true, Traefik routes as soon as
  // the task does - 502 until then, 200 after, with no rerun needed.
  // The user is told the honest state separately through siteReady.
  endpoints: [{ addresses: [host || '0.0.0.0'], conditions: { ready: haveAddr } }]
});

const bodyNomadIngress = JSON.stringify({
  apiVersion: 'networking.k8s.io/v1', kind: 'Ingress',
  metadata: { name: 'site', labels: { 'provisioned-by': 'n8n' } },
  spec: { ingressClassName: 'traefik',
    rules: [{ host: a.siteHost, http: { paths: [{ path: '/', pathType: 'Prefix',
      backend: { service: { name: 'site-nomad-svc', port: { number: 80 } } } }] } }] }
});

return [{ json: {
  nomadHost: host, nomadPort: port, haveAddr, allocRunning,
  allocStatus: pick.allocStatus, allocCount: pick.allocCount,
  siteHost: a.siteHost, siteUrl: a.siteUrl,
  bodyNomadService, bodyNomadSlice, bodyNomadIngress
} }];

// The ONLY thing the namespace creator needs. Passing one explicit,
// named field keeps the sub-workflow trivial to read and means it can
// never depend on the shape of whatever ran before it here.
const ns = $('Analyse repo').first().json.nomadNamespace;
return [{ json: { namespace: ns } }];

// THE PROMPT. Deliberately constrained: the model is given FACTS read
// from the repo and a fixed set of rules, and asked for one artefact.
// It decides nothing about the platform, the quota, the namespace or
// the port the Service will use - it writes text that Kaniko then
// treats exactly like any human-written Dockerfile.
//
// SCOPE, enforced here and documented in Part 23: ONE container. No
// separate database/cache/broker server. An embedded file-based store
// (SQLite) is fine because it lives inside the same container.
const a = $('Analyse repo').first().json;

let manifest = '';
try {
  const m = $('Repo manifest').first().json;
  const raw = (typeof m === 'string') ? m : (m && (m.data || m.body || ''));
  manifest = String(raw || '');
  // A 404 page is not a manifest. Treat it as absent rather than feeding
  // the model an error document as though it were project metadata.
  if (/^404: Not Found/.test(manifest)) manifest = '';
} catch (e) { manifest = ''; }

const SYS = [
'You write Dockerfiles. Output ONLY the Dockerfile text.',
'',
'Rules, all mandatory:',
'- Output raw Dockerfile content and nothing else: no explanation, no',
'  commentary, no markdown, no ``` fences.',
'- ONE container only. Never assume a separate database, cache or message',
'  broker exists. An embedded file-based database (SQLite) is fine.',
'- Start FROM an official minimal image matched to the project',
'  (node:20-alpine, python:3.12-slim, golang:1.22-alpine, nginx:alpine).',
'- If the project needs a build step, use multi-stage and copy only the',
'  built artefact into the final stage.',
'- Install dependencies from the project own manifest with a',
'  reproducible command (npm ci, pip install -r, go mod download).',
'- Never run apt-get upgrade. Never use interactive commands.',
'- End with EXPOSE <port> and a CMD that runs the app in the foreground.',
'  EXPOSE must be the port the application really listens on.',
'- When copying application files, COPY the whole project directory',
'  rather than naming individual files. Naming files misses assets that',
'  are referenced at runtime (images, fonts, sub-directories) and',
'  produces a site with broken links.',
'- If the project is static files with no build step, serve it with',
'  nginx:alpine and EXPOSE 80.',
'- No VOLUME. No ENTRYPOINT script unless you create it in the Dockerfile.'
].join(String.fromCharCode(10));

const lines = [
  'Repository: ' + a.owner + '/' + a.repo,
  'Languages: ' + (Object.keys(a.languages || {}).join(', ') || 'unknown'),
  'Root files: ' + (a.files || []).slice(0, 40).join(', '),
  'Manifest (' + (a.manifestName || 'none found') + '):',
  manifest ? manifest.slice(0, 1500) : '(no manifest file in this repo)',
  '',
  'README (first 400 chars): ' + String(a.readme || '').slice(0, 400),
  '',
  'Generate the Dockerfile.'
];
if (a.looksStatic) lines.splice(3, 0,
  'This repo looks like plain static files with no build step.');

const dockerPrompt = JSON.stringify({
  model: 'openai/gpt-oss-20b', temperature: 0, max_tokens: 1024,
  reasoning_effort: 'low',
  messages: [{ role: 'system', content: SYS },
             { role: 'user', content: lines.join(String.fromCharCode(10)) }]
});

return [{ json: { ...a, dockerSys: SYS, dockerPrompt, manifestChars: manifest.length } }];

// Extract the Dockerfile, validate it, and build the Kaniko Job body.
// The model is asked for raw text, but a model that ignores that and
// wraps its answer in ``` fences must not be able to produce a broken
// build - so the fences are stripped rather than trusted not to appear.
const a = $('Analyse repo').first().json;
const v = $('Validate input').first().json;
const attempt = 1;

let text = '';
try {
  const r = $('Generate a Dockerfile').first().json;
  text = String(r?.choices?.[0]?.message?.content ?? '');
} catch (e) { text = ''; }

// Strip markdown fences and any leading prose before the first FROM.
text = text.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '').trim();
const fromAt = text.search(/^\s*FROM\s+\S+/mi);
if (fromAt > 0) text = text.slice(fromAt);

// VALIDATION. Anything that fails here means no build is attempted at
// all - the tenant keeps the working starter rather than being handed a
// build that cannot succeed.
const tooBig = text.length > 8192;
const hasFrom = /^\s*FROM\s+\S+/mi.test(text);
const usable = Boolean(text) && hasFrom && !tooBig;

// The port comes from the generated EXPOSE, exactly as it is read from a
// human-written Dockerfile. If the model omitted it we fall back to 80
// and SAY SO through portSource, never silently.
let aiPort = 80, aiPortSource = 'default';
const m = text.match(/^\s*EXPOSE\s+([0-9]{2,5})/mi);
if (m) { aiPort = parseInt(m[1], 10); aiPortSource = 'dockerfile'; }

const stamp = Math.floor(Date.now() / 1000);
const jobName = ('ai' + attempt + '-' + v.namespace + '-' + stamp).slice(0, 60);
const imageRef = '10.43.200.50:5000/' + v.namespace + '/app:ai' + attempt + '-' + stamp;

// THE SANDBOX IS IDENTICAL TO THE HUMAN-WRITTEN PATH. Same namespace,
// same `builder` service account, same dropped capabilities, same
// resource limits, same NetworkPolicy. An AI-authored Dockerfile gets no
// special treatment and no special trust - the pipeline already builds
// arbitrary Dockerfiles written by strangers on public GitHub.
//
// The ONLY difference is delivery: an init container writes the
// generated text into an emptyDir and kaniko reads it by absolute path.
// Hand-proved before this was written; needs no extra RBAC. Its requests
// are tiny so the pod's effective request stays 512Mi and the build
// namespace still admits exactly two concurrent builds.
const bodyAiBuild = JSON.stringify({
  apiVersion: 'batch/v1', kind: 'Job',
  metadata: { name: jobName, labels: { tenant: v.username, aibuild: 'yes' } },
  spec: {
    // 900s, the SAME bound the human-written path uses. 420s was my
    // number and it killed two perfectly good Dockerfiles: the
    // hand-proof of this very build took 552s at this uplink.
    activeDeadlineSeconds: 900,
    backoffLimit: 0,
    ttlSecondsAfterFinished: 3600,
    template: {
      metadata: { labels: { app: 'kaniko-build', tenant: v.username } },
      spec: {
        restartPolicy: 'Never',
        serviceAccountName: 'builder',
        automountServiceAccountToken: false,
        securityContext: { seccompProfile: { type: 'RuntimeDefault' } },
        volumes: [{ name: 'gen', emptyDir: {} }],
        initContainers: [{
          name: 'write-dockerfile',
          image: 'busybox:1.36',
          command: ['sh', '-c', 'printf %s "$DOCKERFILE" > /gen/Dockerfile'],
          env: [{ name: 'DOCKERFILE', value: text }],
          volumeMounts: [{ name: 'gen', mountPath: '/gen' }],
          resources: { requests: { cpu: '10m', memory: '16Mi' },
                       limits: { cpu: '100m', memory: '64Mi' } }
        }],
        containers: [{
          name: 'kaniko',
          image: 'gcr.io/kaniko-project/executor:v1.23.2',
          args: [
            '--context=git://github.com/' + v.owner + '/' + v.repo +
              '.git#refs/heads/' + a.defaultBranch,
            '--dockerfile=/gen/Dockerfile',
            '--destination=' + imageRef,
            '--insecure', '--skip-tls-verify', '--single-snapshot',
            '--verbosity=info'
          ],
          securityContext: {
            privileged: false, allowPrivilegeEscalation: false,
            capabilities: { drop: ['ALL'], add: ['CHOWN','FOWNER','DAC_OVERRIDE'] }
          },
          volumeMounts: [{ name: 'gen', mountPath: '/gen' }],
          resources: { requests: { cpu: '300m', memory: '512Mi' },
                       limits: { cpu: '1', memory: '1Gi' } }
        }]
      }
    }
  }
});

return [{ json: { ...a, attempt, dockerfile: text, usable, hasFrom, tooBig,
  aiPort, aiPortSource, aiJobName: jobName, aiImageRef: imageRef,
  bodyAiBuild } }];

// ONE retry, and only one. The build error is fed back so the model can
// correct a real fault rather than resample blindly. If this attempt
// also fails the tenant keeps the working starter and is told plainly -
// no third try, no loop.
const c = $('Check the generated Dockerfile').first().json;
let log = '';
try {
  const r = $('Read the build log').first().json;
  log = String((typeof r === 'string') ? r : (r?.data ?? r?.body ?? ''));
} catch (e) { log = ''; }

const user = [
  'The Dockerfile below FAILED to build. Fix the cause and output a',
  'corrected Dockerfile, following the same rules.',
  '',
  '--- your previous Dockerfile ---',
  c.dockerfile,
  '--- build error (last 1500 chars) ---',
  log.slice(-1500) || '(no build log was available)'
].join(String.fromCharCode(10));

const dockerPrompt = JSON.stringify({
  model: 'openai/gpt-oss-20b', temperature: 0, max_tokens: 1024,
  reasoning_effort: 'low',
  messages: [{ role: 'system', content: c.dockerSys ||
                $('Write the Dockerfile prompt').first().json.dockerSys },
             { role: 'user', content: user }]
});
return [{ json: { ...c, dockerPrompt, buildLogChars: log.length } }];

// Extract the Dockerfile, validate it, and build the Kaniko Job body.
// The model is asked for raw text, but a model that ignores that and
// wraps its answer in ``` fences must not be able to produce a broken
// build - so the fences are stripped rather than trusted not to appear.
const a = $('Analyse repo').first().json;
const v = $('Validate input').first().json;
const attempt = 2;

let text = '';
try {
  const r = $('Generate a Dockerfile (retry)').first().json;
  text = String(r?.choices?.[0]?.message?.content ?? '');
} catch (e) { text = ''; }

// Strip markdown fences and any leading prose before the first FROM.
text = text.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '').trim();
const fromAt = text.search(/^\s*FROM\s+\S+/mi);
if (fromAt > 0) text = text.slice(fromAt);

// VALIDATION. Anything that fails here means no build is attempted at
// all - the tenant keeps the working starter rather than being handed a
// build that cannot succeed.
const tooBig = text.length > 8192;
const hasFrom = /^\s*FROM\s+\S+/mi.test(text);
const usable = Boolean(text) && hasFrom && !tooBig;

// The port comes from the generated EXPOSE, exactly as it is read from a
// human-written Dockerfile. If the model omitted it we fall back to 80
// and SAY SO through portSource, never silently.
let aiPort = 80, aiPortSource = 'default';
const m = text.match(/^\s*EXPOSE\s+([0-9]{2,5})/mi);
if (m) { aiPort = parseInt(m[1], 10); aiPortSource = 'dockerfile'; }

const stamp = Math.floor(Date.now() / 1000);
const jobName = ('ai' + attempt + '-' + v.namespace + '-' + stamp).slice(0, 60);
const imageRef = '10.43.200.50:5000/' + v.namespace + '/app:ai' + attempt + '-' + stamp;

// THE SANDBOX IS IDENTICAL TO THE HUMAN-WRITTEN PATH. Same namespace,
// same `builder` service account, same dropped capabilities, same
// resource limits, same NetworkPolicy. An AI-authored Dockerfile gets no
// special treatment and no special trust - the pipeline already builds
// arbitrary Dockerfiles written by strangers on public GitHub.
//
// The ONLY difference is delivery: an init container writes the
// generated text into an emptyDir and kaniko reads it by absolute path.
// Hand-proved before this was written; needs no extra RBAC. Its requests
// are tiny so the pod's effective request stays 512Mi and the build
// namespace still admits exactly two concurrent builds.
const bodyAiBuild = JSON.stringify({
  apiVersion: 'batch/v1', kind: 'Job',
  metadata: { name: jobName, labels: { tenant: v.username, aibuild: 'yes' } },
  spec: {
    // 900s, the SAME bound the human-written path uses. 420s was my
    // number and it killed two perfectly good Dockerfiles: the
    // hand-proof of this very build took 552s at this uplink.
    activeDeadlineSeconds: 900,
    backoffLimit: 0,
    ttlSecondsAfterFinished: 3600,
    template: {
      metadata: { labels: { app: 'kaniko-build', tenant: v.username } },
      spec: {
        restartPolicy: 'Never',
        serviceAccountName: 'builder',
        automountServiceAccountToken: false,
        securityContext: { seccompProfile: { type: 'RuntimeDefault' } },
        volumes: [{ name: 'gen', emptyDir: {} }],
        initContainers: [{
          name: 'write-dockerfile',
          image: 'busybox:1.36',
          command: ['sh', '-c', 'printf %s "$DOCKERFILE" > /gen/Dockerfile'],
          env: [{ name: 'DOCKERFILE', value: text }],
          volumeMounts: [{ name: 'gen', mountPath: '/gen' }],
          resources: { requests: { cpu: '10m', memory: '16Mi' },
                       limits: { cpu: '100m', memory: '64Mi' } }
        }],
        containers: [{
          name: 'kaniko',
          image: 'gcr.io/kaniko-project/executor:v1.23.2',
          args: [
            '--context=git://github.com/' + v.owner + '/' + v.repo +
              '.git#refs/heads/' + a.defaultBranch,
            '--dockerfile=/gen/Dockerfile',
            '--destination=' + imageRef,
            '--insecure', '--skip-tls-verify', '--single-snapshot',
            '--verbosity=info'
          ],
          securityContext: {
            privileged: false, allowPrivilegeEscalation: false,
            capabilities: { drop: ['ALL'], add: ['CHOWN','FOWNER','DAC_OVERRIDE'] }
          },
          volumeMounts: [{ name: 'gen', mountPath: '/gen' }],
          resources: { requests: { cpu: '300m', memory: '512Mi' },
                       limits: { cpu: '1', memory: '1Gi' } }
        }]
      }
    }
  }
});

return [{ json: { ...a, attempt, dockerfile: text, usable, hasFrom, tooBig,
  aiPort, aiPortSource, aiJobName: jobName, aiImageRef: imageRef,
  bodyAiBuild } }];

// Whichever attempt succeeded supplies the image and the port. Reading
// it from the winning attempt's own record - rather than assuming the
// second - keeps the two paths from silently diverging.
let src = null;
try { src = $('Check the retry Dockerfile').first().json; } catch (e) { src = null; }
if (!src || !src.aiImageRef) {
  try { src = $('Check the generated Dockerfile').first().json; } catch (e) { src = null; }
}
const v = $('Validate input').first().json;

// UPGRADE IN PLACE. The built image goes into the SAME Deployment the
// starter created - same name, same labels - so this is a rolling update
// of one object rather than a Service selector moving between two
// Deployments. That is Part 23 item 16's recommended fix, applied here
// from the start: the starter keeps serving until the built pod is
// Ready, so a slow or broken pull cannot take the site down.
const bodyUpgrade = JSON.stringify({
  apiVersion: 'apps/v1', kind: 'Deployment',
  metadata: { name: 'starter', labels: { app: 'starter', 'built-by': 'kaniko-ai' } },
  spec: {
    replicas: 1,
    selector: { matchLabels: { app: 'starter' } },
    template: {
      metadata: { labels: { app: 'starter' } },
      spec: { containers: [{
        name: 'app', image: src.aiImageRef, imagePullPolicy: 'IfNotPresent',
        resources: { requests: { cpu: '50m', memory: '64Mi' },
                     limits: { cpu: '500m', memory: '512Mi' } }
      }] }
    }
  }
});

// The Service must follow the generated EXPOSE, or the tenant gets a
// link that 502s - the exact failure of Problem #130.
const bodyUpgradeSvc = JSON.stringify({
  apiVersion: 'v1', kind: 'Service',
  metadata: { name: 'site-k8s', labels: { 'provisioned-by': 'n8n' } },
  spec: { selector: { app: 'starter' },
    ports: [{ name: 'http', port: 80, targetPort: src.aiPort || 80 }] }
});

// --- the Nomad form of the same win --------------------------------
// Nomad pulls over the LAN address; Kaniko pushed to the ClusterIP.
// Same image, same digest, two doors (as the human-built path does).
const a = $('Analyse repo').first().json;
const nomadAiImage = String(src.aiImageRef || '')
  .replace('10.43.200.50:5000', '192.168.1.50:5000');

// Same job ID as the starter, so this REPLACES it rather than running
// a second workload beside it. The port comes from the generated
// EXPOSE, and the restart policy is the one from Problem #133 - Nomad
// gives up after 2 attempts by default and would die permanently on a
// pull that is momentarily unavailable.
const bodyNomadAiJob = JSON.stringify({
  Job: {
    ID: a.nomadJobId, Name: a.nomadJobId, Type: 'service',
    Namespace: a.nomadNamespace, Datacenters: ['*'],
    TaskGroups: [{
      Name: 'app', Count: 1,
      Networks: [{ DynamicPorts: [{ Label: 'http', To: src.aiPort || 80 }] }],
      RestartPolicy: { Attempts: 20, Interval: 3600000000000,
                       Delay: 20000000000, Mode: 'delay' },
      Tasks: [{
        Name: 'app', Driver: 'docker',
        Config: { image: nomadAiImage, ports: ['http'] },
        Resources: { CPU: 200, MemoryMB: 256 }
      }]
    }]
  }
});

return [{ json: { namespace: v.namespace, aiImageRef: src.aiImageRef,
  aiPort: src.aiPort, aiPortSource: src.aiPortSource, attempt: src.attempt,
  bodyUpgrade, bodyUpgradeSvc, bodyNomadAiJob, nomadAiImage,
  nomadJobId: a.nomadJobId, nomadNamespace: a.nomadNamespace,
  isNomad: $('Pick from fixed menu').first().json.choice === 'nomad' } }];

// The job was just REPLACED, so its old allocation is still listed
// alongside the new one and carries the OLD port. Newest-running-first,
// exactly as the starter path does - picking wrongly would wire the
// tenant to a port nothing listens on.
let allocs = [];
try { allocs = $input.all().map(i => i.json).filter(x => x && x.ID); }
catch (e) { allocs = []; }
const running = allocs.filter(x => x.ClientStatus === 'running');
const pool = running.length ? running : allocs;
pool.sort((x, y) => (y.CreateIndex || 0) - (x.CreateIndex || 0));
const chosen = pool[0] || null;
return [{ json: { allocId: chosen ? chosen.ID : '',
  allocStatus: chosen ? chosen.ClientStatus : null,
  havePlacement: Boolean(chosen && chosen.ClientStatus === 'running') } }];

// ONLY the EndpointSlice changes. `site-nomad-svc` and the Ingress were
// created by this submission's starter path and an image swap does not
// touch either - re-applying them would be noise that could mask a real
// change. The port is READ from the new allocation, never carried over.
const wb = $('Which build won?').first().json;
const alloc = $input.first().json || {};

let host = null, port = null;
try {
  const ports = ((alloc.AllocatedResources || {}).Shared || {}).Ports || [];
  const p = ports.find(x => x.Label === 'http') || ports[0];
  if (p) { host = p.HostIP || null; port = p.Value || null; }
} catch (e) { host = null; port = null; }
const haveAddr = Boolean(host && port);

const bodyAiSlice = JSON.stringify({
  apiVersion: 'discovery.k8s.io/v1', kind: 'EndpointSlice',
  metadata: { name: 'site-nomad',
    labels: { 'kubernetes.io/service-name': 'site-nomad-svc',
              'provisioned-by': 'n8n' } },
  addressType: 'IPv4',
  ports: [{ name: 'http', port: port || 0, protocol: 'TCP' }],
  endpoints: [{ addresses: [host || '0.0.0.0'], conditions: { ready: haveAddr } }]
});

return [{ json: { namespace: wb.namespace, haveAddr, nomadHost: host,
  nomadPort: port, aiImageRef: wb.nomadAiImage, bodyAiSlice } }];

// WHO OWNS THIS NAMESPACE? The whole point of Phase 1.
//
// `owner` is written by every submission from now on. Namespaces created
// before this change carry only `tenant`, so both are read - a legacy
// tenant must not be locked out of their own project.
//
// FAIL CLOSED. If ownership cannot be established at all - no labels, or
// the namespace could not be read - we do NOT proceed. Deploying into a
// namespace whose owner is unknown is exactly the failure this check
// exists to prevent, and 'unknown' is not 'mine'.
const v = $('Validate input').first().json;
let labels = null, readable = false;
try {
  const j = $input.first().json;
  if (j && j.kind === 'Namespace' && j.metadata) {
    labels = j.metadata.labels || {};
    readable = true;
  }
} catch (e) { labels = null; }

const owner = labels ? (labels.owner || labels.tenant || '') : '';
const ours = readable && owner === v.username;

// A namespace with no ownership label at all is not assumed to be ours.
const nameTaken = readable && !ours;
const ownerUnknown = !readable || !owner;

return [{ json: { ...v, nsOwner: owner, ours, nameTaken, ownerUnknown,
  nsReadable: readable } }];
